// Zella - Follow-up Emails: turn one claimed follow-up task into a "prepare this email" request.
// Reactivation is marketing, so it needs the person's opt-in. The others follow up on something
// the person asked for. Anything unknown is skipped with a visible reason, never dropped silently.
const t = $json;
const skip = (reason) => ({ json: { task_id: t.task_id, finish: { rpc: 'zella_skip_followup_task', body: { p_task_id: t.task_id, p_reason: reason } } } });

const kinds = {
  no_show_follow_up: { key: 'no_show_follow_up', purpose: 'transactional' },
  post_appointment_follow_up: { key: 'post_appointment_follow_up', purpose: 'transactional' },
  quote_follow_up: { key: 'quote_follow_up', purpose: 'transactional' },
  lead_reactivation: { key: 'lead_reactivation', purpose: 'marketing' },
  welcome_new_customer: { key: 'welcome_new_customer', purpose: 'transactional' },
  feedback_request: { key: 'feedback_request', purpose: 'transactional' },
  cancellation_confirmation: { key: 'cancellation_confirmation', purpose: 'transactional' },
  record_status_update: { key: 'record_status_update', purpose: 'transactional' },
  service_due: { key: 'service_due', purpose: 'transactional' },
  no_response_follow_up: { key: 'no_response_follow_up', purpose: 'transactional' },
  reschedule_confirmation: { key: 'reschedule_confirmation', purpose: 'transactional' },
  booking_follow_up: { key: 'booking_follow_up', purpose: 'transactional' },
  service_completed: { key: 'service_completed', purpose: 'transactional' },
  lead_follow_up: { key: 'lead_follow_up', purpose: 'transactional' },
  lead_final_follow_up: { key: 'lead_final_follow_up', purpose: 'transactional' },
};
// A callback that ran out of tries leaves a task behind. The message depends on why the callback existed.
const byReason = { missed_call: 'missed_call_follow_up', new_lead: 'lead_acknowledgement' };
let k = kinds[t.kind];
if (t.kind === 'callback_sms') {
  const key = byReason[t.callback_reason];
  if (!key) return skip('unknown_callback_reason:' + String(t.callback_reason).slice(0, 30));
  k = { key, purpose: 'transactional' };
}
if (t.channel !== 'email') return skip('channel_not_email:' + t.channel);
if (!k) return skip('unknown_followup_kind:' + t.kind);

const vars = {};
if (t.vars && typeof t.vars === 'object') {
  for (const [key, val] of Object.entries(t.vars)) if (typeof val === 'string') vars[key] = val.slice(0, 300);
}

return {
  json: {
    task_id: t.task_id,
    business_id: t.business.id,
    customer_id: t.customer.id,
    template_key: k.key,
    prepare: { p_business_id: t.business.id, p_customer_id: t.customer.id, p_template_key: k.key, p_vars: vars, p_purpose: k.purpose },
    finish: null,
  },
};

// Zella - Follow-up Emails: read the answer from "prepare" and decide what happens to this task.
const plan = $('Plan').item.json;
const status = Number($json.statusCode);
const b = $json.body && typeof $json.body === 'object' ? $json.body : {};
const skip = (reason) => ({ json: { task_id: plan.task_id, finish: { rpc: 'zella_skip_followup_task', body: { p_task_id: plan.task_id, p_reason: reason } } } });
const fail = (reason) => ({ json: { task_id: plan.task_id, finish: { rpc: 'zella_complete_followup_task', body: { p_task_id: plan.task_id, p_outcome: 'failed', p_notes: reason, p_retry_in_minutes: 15 } } } });

if (!(status >= 200 && status < 300)) return fail('The database call zella_prepare_email returned ' + status + '.');
if (b.allowed !== true) return skip(String(b.reason || 'not_allowed').slice(0, 60));
if (b.live === true && !b.from) return fail('sender_address_not_set');

return {
  json: {
    task_id: plan.task_id,
    live: b.live === true,
    from: b.from || null,
    from_name: b.from_name || '',
    unsubscribe_url: typeof b.unsubscribe_url === 'string' && /^https:\/\/[^\s]+$/.test(b.unsubscribe_url) ? b.unsubscribe_url : null,
    to: b.to,
    subject: b.subject,
    text: b.body_text,
    html: b.body_html,
    finish: null,
    log: {
      p_business_id: plan.business_id,
      p_customer_id: plan.customer_id,
      p_to: b.to,
      p_from: b.from || '',
      p_subject: b.subject,
      p_body_text: b.body_text,
      p_body_html: b.body_html,
      p_dedupe_key: 'task:' + plan.task_id,
      p_status: b.live === true ? 'queued' : 'dry_run',
      p_meta: { task_id: plan.task_id, template_id: b.template_id, template_version: b.template_version, dry_run: b.live !== true },
    },
  },
};

// Zella - Follow-up Emails: after the message is logged, decide whether to really send.
// A repeat of the same task is never sent twice. In dry-run nothing is sent.
const d = $('Decide').item.json;
const status = Number($json.statusCode);
const b = $json.body && typeof $json.body === 'object' ? $json.body : {};
const done = (rpc, body) => ({ json: { task_id: d.task_id, finish: { rpc, body } } });
const complete = (outcome, notes) => done('zella_complete_followup_task', { p_task_id: d.task_id, p_outcome: outcome, p_notes: notes, p_retry_in_minutes: 15 });

if (!(status >= 200 && status < 300)) return complete('failed', 'The database call zella_log_outbound_email returned ' + status + '.');
if (b.duplicate === true) {
  if (b.status === 'sent' || b.status === 'delivered') return complete('email_sent', null);
  return done('zella_skip_followup_task', { p_task_id: d.task_id, p_reason: 'duplicate_suppressed' });
}
if (d.live !== true) return done('zella_skip_followup_task', { p_task_id: d.task_id, p_reason: 'dry_run: no email was sent' });

const name = String(d.from_name || '').replace(/[\r\n"<>]+/g, ' ').trim();
const resend = { from: name ? name + ' <' + d.from + '>' : d.from, to: [d.to], subject: d.subject, text: d.text, html: d.html };
// Marketing email carries an unsubscribe header for mail apps as well as the link in the body.
if (d.unsubscribe_url) resend.headers = { 'List-Unsubscribe': '<' + d.unsubscribe_url + '>' };
return { json: { task_id: d.task_id, message_id: b.id, finish: null, resend } };

// Zella - Follow-up Emails: turn the provider's answer into the message update and the task result.
// The provider's response text is never stored, only its status and a short error name.
const prev = $('After log').item.json;
const status = Number($json.statusCode);
const b = $json.body && typeof $json.body === 'object' ? $json.body : {};
const externalId = b.id ? String(b.id) : null;
const ok = status >= 200 && status < 300 && !!externalId;
const name = typeof b.name === 'string' && /^[a-z_]{1,40}$/.test(b.name) ? ' (' + b.name + ')' : '';
const error = ok ? null : 'The email provider returned ' + status + name + '.';

return {
  json: {
    task_id: prev.task_id,
    update: { p_id: prev.message_id, p_status: ok ? 'sent' : 'failed', p_external_id: externalId, p_error: error },
    finish: { rpc: 'zella_complete_followup_task', body: { p_task_id: prev.task_id, p_outcome: ok ? 'email_sent' : 'failed', p_notes: error, p_retry_in_minutes: 15 } },
  },
};
